import type { VariantProps } from "tailwind-variants";

import { tv } from "tailwind-variants";

const avatar = tv({
  slots: {
    root: [
      "relative inline-flex items-center justify-center overflow-hidden rounded-full bg-muted leading-none text-muted-foreground select-none",
      "[&_svg]:shrink-0",
    ],
    image: [
      "absolute inset-0 size-full object-cover transition-opacity duration-150 ease-default",
      "data-ending-style:opacity-0",
      "data-error:invisible",
      "data-loading:invisible",
      "data-starting-style:opacity-0",
    ],
    fallback: "absolute inset-0 flex size-full items-center justify-center",
  },
  variants: {
    size: {
      lg: {
        root: "size-10 text-base [&_svg:not([class*='size-'])]:size-5",
        fallback: "text-base",
      },
      md: {
        root: "size-9 text-sm [&_svg:not([class*='size-'])]:size-4.5",
        fallback: "text-sm",
      },
      sm: {
        root: "size-8 text-xs [&_svg:not([class*='size-'])]:size-4",
        fallback: "text-xs",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

type AvatarVariantProps = VariantProps<typeof avatar>;

export { avatar };
export type { AvatarVariantProps };

"use client";

import {
  Avatar as BaseAvatar,
  type ImageLoadingStatus,
} from "@base-ui/react/avatar";
import { createContext, useContext } from "react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { avatar, type AvatarVariantProps } from "./avatar.style";

type AvatarContext = AvatarVariantProps;

const AvatarContext = createContext<AvatarContext>({
  size: "md",
});

function useAvatar() {
  return useContext(AvatarContext);
}

type AvatarImageLoadingStatus = ImageLoadingStatus;

function Avatar({
  size,
  className,
  children,
  ...props
}: BaseAvatar.Root.Props & AvatarVariantProps) {
  return (
    <AvatarContext.Provider value={{ size }}>
      <BaseAvatar.Root
        data-slot="avatar"
        className={mergeSlotClassName(avatar({ size }).root, className)}
        {...props}
      >
        {children}
      </BaseAvatar.Root>
    </AvatarContext.Provider>
  );
}

function AvatarImage({ className, ...props }: BaseAvatar.Image.Props) {
  return (
    <BaseAvatar.Image
      data-slot="avatar-image"
      className={mergeSlotClassName(avatar().image, className)}
      {...props}
    />
  );
}

function AvatarFallback({ className, ...props }: BaseAvatar.Fallback.Props) {
  const { size } = useAvatar();

  return (
    <BaseAvatar.Fallback
      data-slot="avatar-fallback"
      className={mergeSlotClassName(avatar({ size }).fallback, className)}
      {...props}
    />
  );
}

export { Avatar, AvatarImage, AvatarFallback };
export type { AvatarImageLoadingStatus };
